public class CollatzChampion {

    public static int longestStartUnder(int n) {
        int best = 1;
        int bestSteps = -1;
        for (int start = 1; start < n; start++) {
            long x = start;
            int steps = 0;
            while (x != 1) {
                if (x % 2 == 0) {
                    x = x / 2;
                } else {
                    x = 3 * x + 1;
                }
                steps++;
            }
            if (steps > bestSteps) {
                bestSteps = steps;
                best = start;
            }
        }
        return best;
    }
}
